use customer_behavior;
select * from customer_shopping_behavior

--Q1. The Total Revenue Generated by male vs female customers?
select gender, sum(purchase_amount) as revenue
from customer_shopping_behavior
group by gender

--Q2. Which customer used a discount but still spent more than average purchase amount?
select customer_id, purchase_amount from
customer_shopping_behavior
where discount_applied = 'Yes'
and purchase_amount >= (
select avg(purchase_amount)
from customer_shopping_behavior)

--Q3 Which are the top 5 products with the highest average review rating
select top 5 item_purchased, 
round(avg(review_rating),2) as "Average Product Rating"
from customer_shopping_behavior
group by item_purchased
order by avg(review_rating) desc;

--Q4 Compare the average purchase amounts between standard and express shipping?
select shipping_type,
round(avg(purchase_amount),2) as avg_pur_amount 
from customer_shopping_behavior
where shipping_type in ('Standard', 'Express')
group by shipping_type

--Q5 Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers
select subscription_status,
count(customer_id) as total_customers,
avg(purchase_amount) as "Avg_spent",
sum(purchase_amount) as total_revenue
from customer_shopping_behavior
where subscription_status in ('Yes', 'No')
group by subscription_status 

--Q6 Which 5 products have the highest percentage of purchases with discounts applied?
select top 5 item_purchased,
round(sum(case when discount_applied = 'Yes' then 1 else 0 end)* 100 / count(*),2) as discount_rate
from customer_shopping_behavior
group by item_purchased
order by discount_rate desc

--Q7 Segment customers into New, Returning and loyal basued on their total number of previous purchases and show the count of each segment
with customer_type as (
select customer_id, previous_purchases,
case
when previous_purchases = 1 then 'New'
when previous_purchases between 2 and 10 then 'Returning'
else 'Loyal'
end as customer_segment
from customer_shopping_behavior
)
select customer_segment, count(*) as Number_of_customers from customer_type
group by customer_segment
order by Number_of_customers desc

--Q8.What are top 3 most purchased products within each category
with item_frequency as (
select category, item_purchased,
count(customer_id) as total_orders,
ROW_NUMBER() over(partition by category order by count(customer_id) desc) as item_rank
from customer_shopping_behavior
group by category, item_purchased
)
select * from item_frequency
where item_rank <= 3

--Q9.Are customers who are repeat buyers(More than 5 previous purchases) also likely to subscribe?
 select subscription_status,
 count(customer_id) as repeat_buyers
 from customer_shopping_behavior
 where previous_purchases > 5
 group by subscription_status
 order by repeat_buyers desc

 --Q10. What is the revenue contribution of each age group
 select age_group, sum(purchase_amount) as total_revenue
 from customer_shopping_behavior
 group by age_group
 order by age_group

   
